  add('PER_WF_EDGE', q'[CONSTRAINT "PER_WFEDGE_VER_FK" FOREIGN KEY ("WF_VERSION_ID") REFERENCES "PER_WF_VERSION" ("WF_VERSION_ID") ENABLE]');
  add('PER_WF_NODE', q'[CONSTRAINT "PER_WFNODE_VER_FK" FOREIGN KEY ("WF_VERSION_ID") REFERENCES "PER_WF_VERSION" ("WF_VERSION_ID") ENABLE]');
  add('PER_WF_NODE', q'[CONSTRAINT "PER_WFNODE_ROLE_FK" FOREIGN KEY ("ASSIGNEE_ROLE_ID") REFERENCES "PER_ROLE" ("ROLE_ID") ENABLE]');
  add('PER_WF_VERSION', q'[CONSTRAINT "PER_WFVER_DEF_FK" FOREIGN KEY ("WF_DEF_ID") REFERENCES "PER_WF_DEF" ("WF_DEF_ID") ENABLE]');
  add('PXT_APP_USER', q'[CONSTRAINT "PXT_APP_USER_PERSON_FK" FOREIGN KEY ("PERSON_ID") REFERENCES "PXT_PERSON" ("PERSON_ID") ENABLE]');
  DBMS_OUTPUT.PUT_LINE('Foreign keys added: ' || n_ok || ', failed: ' || n_fail);
END;
